 79	@@ -0,0 +1,59 @@
 80	+// Local Nx plugin (#3151): appends the lockfile to every `lint` target that
 81	+// @nx/oxlint infers. Type-aware oxlint reads installed type packages that Nx
 82	+// hashes for this executor only through the lockfile (a package only a
 83	+// tsconfig names in `types`; `externalDependencies` is ignored on executor
 84	+// targets). It must stay after @nx/oxlint in nx.json, so the `'...'` spread
 85	+// has the inferred inputs to keep. It takes every project.json with a
 86	+// tsconfig.json in its folder or an ancestor below the root (the `tools-*`
 87	+// projects share `tools/tsconfig.json`), which today is every project oxlint
 88	+// lints; the root project's hand-written `lint` names the lockfile itself.
 89	+import { existsSync } from 'node:fs';
 90	+import { dirname, join } from 'node:path';
 91	+
 92	+const TSCONFIG = 'tsconfig.json';
 93	+// Must match the targetName @nx/oxlint gets in nx.json.
 94	+const DEFAULT_TARGET_NAME = 'lint';
 95	+// Only a project.json marks a project root here: the root package.json has
 96	+// no `workspaces`, so Nx takes no folder with just a package.json as a project.
 97	+const PROJECT_FILE = 'project.json';
 98	+const WORKSPACE_ROOT_PROJECT = '.';
 99	+export const LOCKFILE_INPUT = '{workspaceRoot}/package-lock.json';
100	+
101	+/**
102	+ * @typedef {{ targetName?: string }} LintLockfileInputOptions
103	+ * @type {import('@nx/devkit').CreateNodes<LintLockfileInputOptions>}
104	+ */
105	+export const createNodes = [
106	+  `**/${PROJECT_FILE}`,
107	+  (projectFiles, options, { workspaceRoot }) => {
108	+    const targetName = options?.targetName ?? DEFAULT_TARGET_NAME;
109	+    return projectFiles
110	+      .map((projectFile) => [projectFile, dirname(projectFile)])
111	+      .filter(([, root]) => root !== WORKSPACE_ROOT_PROJECT)
112	+      .filter(([, root]) => hasProjectTsconfig(workspaceRoot, root))
113	+      .map(([projectFile, root]) => [
114	+        projectFile,
115	+        {
116	+          projects: {
117	+            [root]: {
118	+              targets: { [targetName]: { inputs: ['...', LOCKFILE_INPUT] } },
119	+            },
120	+          },
121	+        },
122	+      ]);
123	+  },
124	+];
125	+
126	+/**
127	+ * Whether the project's folder or one of its ancestors below the workspace
128	+ * root holds a tsconfig.json. The root's own belongs to the root scripts.
129	+ */
130	+function hasProjectTsconfig(workspaceRoot, root) {
131	+  for (let folder = root; folder !== WORKSPACE_ROOT_PROJECT;) {
132	+    if (existsSync(join(workspaceRoot, folder, TSCONFIG))) {
133	+      return true;
134	+    }
135	+    folder = dirname(folder);
136	+  }
137	+  return false;
138	+}
