143	+++ b/tools/nx/lint-lockfile-input.test.mjs
144	@@ -0,0 +1,119 @@
145	+// Spec of the local Nx plugin that makes the lockfile an input of every
146	+// inferred oxlint `lint` target (#3151); the root project's hand-written `lint`
147	+// is checked by tools/ci/root-lint.test.mjs. Each plugin case lays out a workspace in a temp folder and runs createNodes on it, as Nx
148	+// does with the files matching its pattern. `describe` and `it` return
149	+// promises `node:test` awaits itself, hence the `void`.
150	+import assert from 'node:assert/strict';
151	+import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
152	+import { tmpdir } from 'node:os';
153	+import { dirname, join, matchesGlob } from 'node:path';
154	+import { after, before, describe, it } from 'node:test';
155	+import { gitLsFiles, readJson } from '../ci/workspace-projects.mjs';
156	+import { createNodes, LOCKFILE_INPUT } from './lint-lockfile-input.mjs';
157	+
158	+const [pattern, inferTargets] = createNodes;
159	+const PROJECT = 'libs/utils/a/project.json';
160	+const TSCONFIG = 'libs/utils/a/tsconfig.json';
161	+const WORKSPACE_ROOT = join(import.meta.dirname, '..', '..');
162	+
163	+let workspaceRoot;
164	+
165	+before(() => {
166	+  workspaceRoot = mkdtempSync(join(tmpdir(), 'lint-lockfile-input-'));
167	+});
168	+
169	+after(() => rmSync(workspaceRoot, { recursive: true, force: true }));
170	+
171	+let caseCount = 0;
172	+
173	+/** Writes the files into a fresh folder below the temp workspace. */
174	+function layOut(files) {
175	+  const caseRoot = `case-${++caseCount}`;
176	+  for (const file of files) {
177	+    const path = join(workspaceRoot, caseRoot, file);
178	+    mkdirSync(dirname(path), { recursive: true });
179	+    writeFileSync(path, '{}');
180	+  }
181	+  return caseRoot;
182	+}
183	+
184	+async function infer(files, projectFiles, options) {
185	+  const caseRoot = layOut(files);
186	+  const results = await inferTargets(
187	+    projectFiles.map((file) => `${caseRoot}/${file}`),
188	+    options,
189	+    { workspaceRoot, nxJsonConfiguration: {} }
190	+  );
191	+  return results.map(([file, result]) => [
192	+    file.slice(caseRoot.length + 1),
193	+    Object.fromEntries(
194	+      Object.entries(result.projects ?? {}).map(([root, project]) => [
195	+        root.slice(caseRoot.length + 1),
196	+        project,
197	+      ])
198	+    ),
199	+  ]);
200	+}
201	+
202	+const LOCKFILE_LINT = {
203	+  targets: { lint: { inputs: ['...', LOCKFILE_INPUT] } },
204	+};
205	+
206	+void describe('lint-lockfile-input plugin', () => {
207	+  void it('matches every project.json', () => {
208	+    assert.ok(matchesGlob(PROJECT, pattern));
209	+    assert.ok(matchesGlob('apps/app/project.json', pattern));
210	+    assert.ok(!matchesGlob('libs/utils/a/package.json', pattern));
211	+  });
212	+
213	+  void it('appends the lockfile to the lint inputs of a project with a tsconfig.json', async () => {
214	+    const results = await infer([PROJECT, TSCONFIG], [PROJECT]);
215	+    assert.deepEqual(results, [[PROJECT, { 'libs/utils/a': LOCKFILE_LINT }]]);
216	+  });
217	+
218	+  void it('takes a nested project typed by an ancestor tsconfig.json', async () => {
219	+    const nested = 'tools/relay/project.json';
220	+    const results = await infer([nested, 'tools/tsconfig.json'], [nested]);
221	+    assert.deepEqual(results, [[nested, { 'tools/relay': LOCKFILE_LINT }]]);
222	+  });
223	+
224	+  void it('skips a project without a tsconfig.json, which oxlint lints not', async () => {
225	+    const results = await infer([PROJECT], [PROJECT]);
226	+    assert.deepEqual(results, []);
227	+  });
228	+
229	+  void it('skips the root project, whose lint is hand-written', async () => {
230	+    const results = await inferTargets(['project.json'], undefined, {
231	+      workspaceRoot: WORKSPACE_ROOT,
232	+      nxJsonConfiguration: {},
233	+    });
234	+    assert.deepEqual(results, []);
235	+  });
236	+
237	+  void it('names the target after the targetName option', async () => {
238	+    const results = await infer([PROJECT, TSCONFIG], [PROJECT], {
239	+      targetName: 'oxlint',
240	+    });
241	+    assert.deepEqual(Object.keys(results[0][1]['libs/utils/a'].targets), [
242	+      'oxlint',
243	+    ]);
244	+  });
245	+});
246	+
247	+void describe('project.json lint targets', () => {
248	+  // Inputs a project.json gives `lint` replace the inferred ones unless they
249	+  // spread them, which would drop the lockfile again.
250	+  void it('keep the lockfile: they spread the inferred inputs or name it', () => {
251	+    const replacing = gitLsFiles()
252	+      .filter(
253	+        (file) => file.endsWith('project.json') && file !== 'project.json'
254	+      )
255	+      .filter((file) => {
256	+        const inputs = readJson(file).targets?.lint?.inputs;
257	+        return (
258	+          inputs && !inputs.includes('...') && !inputs.includes(LOCKFILE_INPUT)
259	+        );
260	+      });
261	+    assert.deepEqual(replacing, []);
262	+  });
263	+});

