 86	+// tsconfig.json in its folder or an ancestor below the root (the `tools-*`
 87	+// projects share `tools/tsconfig.json`), which today is every project oxlint
 88	+// lints; the root project's hand-written `lint` names the lockfile itself.
 89	+import { existsSync } from 'node:fs';
