100	+
101	+/**
102	+ * @typedef {{ targetName?: string }} LintLockfileInputOptions
103	+ * @type {import('@nx/devkit').CreateNodes<LintLockfileInputOptions>}
104	+ */
105	+export const createNodes = [
106	+  `**/${PROJECT_FILE}`,
107	+  (projectFiles, options, { workspaceRoot }) => {
108	+    const targetName = options?.targetName ?? DEFAULT_TARGET_NAME;
109	+    return projectFiles
110	+      .map((projectFile) => [projectFile, dirname(projectFile)])
111	+      .filter(([, root]) => root !== WORKSPACE_ROOT_PROJECT)
112	+      .filter(([, root]) => hasProjectTsconfig(workspaceRoot, root))
113	+      .map(([projectFile, root]) => [
114	+        projectFile,
115	+        {
116	+          projects: {
117	+            [root]: {
118	+              targets: { [targetName]: { inputs: ['...', LOCKFILE_INPUT] } },
119	+            },
120	+          },
121	+        },
122	+      ]);
123	+  },
124	+];
